#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    long long ascent = 0;
    vector<pair<int, int>> events;
    events.reserve(2LL * n);

    for (int i = 0; i < n; ++i) {
        int len;
        cin >> len;

        int first = 0, last = 0;
        int previous = INT_MAX;
        bool hasAscent = false;

        for (int j = 0; j < len; ++j) {
            int x;
            cin >> x;

            if (j == 0) first = x;
            if (j == len - 1) last = x;
            if (x > previous) hasAscent = true;

            previous = x;
        }

        if (hasAscent) {
            ++ascent;
        } else {
            events.emplace_back(first, 1);
            events.emplace_back(last, 2);
        }
    }

    sort(events.begin(), events.end());

    long long countFirst = 0;
    long long badPairs = 0;

    for (const auto &[value, type] : events) {
        if (type == 1) {
            ++countFirst;
        } else {
            badPairs += countFirst;
        }
    }

    long long nonAscent = n - ascent;
    long long answer = 1LL * n * n - badPairs;

    cout << answer << '\n';
    return 0;
}

